import{_ as e,o as r,c as a,a5 as o}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"Color Cause","description":"","frontmatter":{"title":"Color Cause"},"headers":[],"relativePath":"classification/color-causes/intro.md","filePath":"classification/color-causes/intro.md","lastUpdated":1790876393000}'),i={name:"classification/color-causes/intro.md"};function s(d,t,n,l,c,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="color-cause" tabindex="-1">Color Cause <a class="header-anchor" href="#color-cause" aria-label="Permalink to &quot;Color Cause&quot;">​</a></h1><p>Color is not an isolated visual label. It is the result of light interacting with matter. This module separates body color from structural optical color, then introduces three common coloration mechanisms:</p><h2 id="first-separate-the-two-paths" tabindex="-1">First Separate the Two Paths <a class="header-anchor" href="#first-separate-the-two-paths" aria-label="Permalink to &quot;First Separate the Two Paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>What happens to light</th><th>Typical result</th></tr></thead><tbody><tr><td>Absorption-based body color</td><td>The gem selectively absorbs visible wavelengths; the remainder reaches the eye</td><td>Ruby, emerald, and sapphire body color</td></tr><tr><td>Structural optical color</td><td>Microstructure scatters, interferes with, or diffracts light; color changes with angle or source</td><td>Opal play-of-color, moonstone sheen, labradorite flash</td></tr></tbody></table><h2 id="three-primary-mechanisms" tabindex="-1">Three Primary Mechanisms <a class="header-anchor" href="#three-primary-mechanisms" aria-label="Permalink to &quot;Three Primary Mechanisms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mechanism</th><th>Summary</th></tr></thead><tbody><tr><td><a href="./transition-metal.html">Transition-Metal Ion Coloration</a></td><td>Transition-metal ions (Cr, Fe, Mn, Co, Ni, V, Cu, Ti) have</td></tr><tr><td>partially filled d or f orbitals. When substituted into a host</td><td></td></tr><tr><td>lattice, crystal-field splitting creates d-d absorption bands</td><td></td></tr><tr><td>in the visible spectrum. The unabsorbed wavelengths produce</td><td></td></tr><tr><td>the gem&#39;s color. This is the dominant cause of color in</td><td></td></tr><tr><td>gemstones and is important in many common colored stones.</td><td></td></tr><tr><td></td><td></td></tr><tr><td><a href="./color-centers.html">Color Centers</a></td><td>Color centers are point defects in a crystal lattice that</td></tr><tr><td>selectively absorb visible light. When an ion is missing</td><td></td></tr><tr><td>(vacancy), extra (interstitial), or substituted by an impurity,</td><td></td></tr><tr><td>nearby electrons or holes become trapped. Their energy levels</td><td></td></tr><tr><td>often fall in the visible range, producing color. Color centers</td><td></td></tr><tr><td>form naturally via radiation, or via artificial irradiation</td><td></td></tr><tr><td>(which may fade with sunlight exposure — a key tell for</td><td></td></tr><tr><td>treated material).</td><td></td></tr><tr><td></td><td></td></tr><tr><td><a href="./charge-transfer.html">Charge Transfer</a></td><td>Charge transfer involves an electron hopping between adjacent</td></tr><tr><td>ions or between different energy states of the same ion, driven</td><td></td></tr><tr><td>by absorbed photons. Compared to d-d transitions, charge-</td><td></td></tr><tr><td>transfer absorption is typically 10²–10⁴ times stronger, so</td><td></td></tr><tr><td>even trace concentrations of the relevant elements can produce</td><td></td></tr><tr><td>saturated, vivid colors. Subtypes include metal–metal (MMCT),</td><td></td></tr><tr><td>oxygen–metal (OMCT), and metal–ligand (MLCT).</td><td></td></tr><tr><td></td><td></td></tr></tbody></table><p>Color categories support observation and retrieval, but they do not replace identification. The same color may arise from different mechanisms; evaluate hue, tone, saturation, lighting, and viewing direction together.</p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gems-gemology" target="_blank" rel="noreferrer">GIA: Gems &amp; Gemology research</a><span>Gem color, optical appearance, and gemological research context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA: Structures Behind the Spectacle</a><span>Structural optical color and microstructure observation clues</span><small>Open source ↗</small></li></ul></aside><p><em>See the <a href="./../intro.html">classification overview</a> for the mineralogical framework.</em></p>',9)])])}const u=e(i,[["render",s]]);export{p as __pageData,u as default};
